    ["Dolanaar"] = { type = "town", faction = "alliance", home = { ["NightElf"] = true },
      { "In Dolanaar, rain scented the houses around the moonwell. The sentinels' patient watch let me lower my guard a little.", tags = { "home" } },
      { "Dolanaar's blue moonwell drew my eye before the houses did. Under the trailing vines, I caught myself speaking softly.", tags = { "!home" } },
    },
    ["Dun Morogh"] = { type = "zone", faction = "alliance", home = { ["Dwarf"] = true, ["Gnome"] = true },
      { "Dun Morogh's cold caught in my throat beneath the snow-heavy pines. Ironforge's familiar mountain made the country feel less empty.", tags = { "home", "!night" } },
      { "Under Dun Morogh's stars, blue snow made the village lamps look warmer. The mountains were familiar company in the dark.", tags = { "home", "night" } },
      { "I felt Dun Morogh's cold in my fingers. Ironforge's gate vanished into the mountain as though the dwarves had persuaded the stone to make room.", tags = { "ally" } },
      { "Snow lay underfoot in Dun Morogh, with Ironforge's mountain ahead. I wondered how many dwarves waited behind that stone.", tags = { "foe" } },
    },
    ["Durotar"] = { type = "zone", faction = "horde", home = { ["Orc"] = true, ["Troll"] = true },
      { "Durotar's heat rose through the red dust at my feet. This was the land we had claimed; I wanted to learn how to belong to it.", tags = { "home", "!night" } },
      { "Durotar's red earth faded to grey as heat left the stones. Orgrimmar's drums carried beyond the hills, a sound I could follow in the dark.", tags = { "home", "night" } },
      { "In Durotar, the red hills closed around the road to Orgrimmar. Under that sun, I began to understand the people who had chosen to stay.", tags = { "ally" } },
      { "Durotar's hot wind drove red dust against me. In the Horde's own country, I no longer trusted the ridges to be empty.", tags = { "foe" } },
    },
    ["Gnomeregan"] = { type = "dungeon", faction = "alliance", home = { ["Gnome"] = true },
      { "I had imagined Gnomeregan's halls so often. Among the troggs and poisonous glow, I still found myself searching for faces I knew.", tags = { "home" } },
      { "Gnomeregan's machines still worked in halls their makers had lost. Under the sickly green light, I wondered who would ever stop the wheels.", tags = { "!home" } },
    },
    ["Ironforge"] = { type = "zone", faction = "alliance", home = { ["Dwarf"] = true },
      { "Ironforge's hammering followed the Great Forge's heat against my face. Above the molten iron, I let my people's noise fill the space the road had left.", tags = { "home" } },
      { "Ironforge's heat met me after the mountain cold. The hammers ringing through the halls were almost comforting after the open country.", tags = { "ally" } },
      { "Ironforge's mountain closed around me amid hammering from every hall. With so many guards, its warmth offered me little comfort.", tags = { "foe" } },
